add_action( 'woocommerce_share', 'perfectpixel_product_share_links' );

function perfectpixel_product_share_links() {
	$url   = rawurlencode( get_permalink() );
	$title = rawurlencode( wp_strip_all_tags( get_the_title() ) );
	$links = array(
		'X'        => 'https://twitter.com/intent/tweet?url=' . $url . '&text=' . $title,
		'Facebook' => 'https://www.facebook.com/sharer/sharer.php?u=' . $url,
		'WhatsApp' => 'https://wa.me/?text=' . $title . '%20' . $url,
	);
	echo '<div class="perfectpixel-share" style="margin-top:1em">' . esc_html( '{{share_links_label}}' );
	foreach ( $links as $name => $href ) {
		printf( ' <a href="%s" target="_blank" rel="noopener noreferrer nofollow">%s</a>', esc_url( $href ), esc_html( $name ) );
	}
	echo '</div>';
}
